695: static int idma_observation_prepare(struct idma_observation *o, bool enabled)
696: {
697: 	u64 magic;
698: 
699: 	if (!enabled)
700: 		return 0;
701: 	o->sequence = ++idma_observation_sequence;
702: 	o->control = idma_get_instance(0);
703: 	if (!o->control)
704: 		return -ENODEV;
705: 	magic = readq(o->control->reg + IDMA_OBS_MAGIC_OFFSET);
706: 	o->path = o->batch && READ_ONCE(idma_path_observe);
707: 	if (o->control->did != 10 ||
708: 	    (magic != IDMA_OBS_MAGIC_V3 &&
709: 	     (o->path || (magic != IDMA_OBS_MAGIC_V2 && (o->batch || magic != IDMA_OBS_MAGIC)))))
710: 		return -EOPNOTSUPP;
711: 	/* Clear previous frozen results; never take ownership of an active session. */
712: 	if (readq(o->control->reg + IDMA_OBS_CONTROL_OFFSET) & 3)
713: 		return -EBUSY;
714: 	writeq(4, o->control->reg + IDMA_OBS_CONTROL_OFFSET);
715: 	return readq(o->control->reg + IDMA_OBS_CONTROL_OFFSET) ? -EIO : 0;
716: }
